# Load packages
library(dplyr)
library(readr)

# Define inputs
# Co-expression network statistics
coexp_file <- file.path(
  "data",
  "external",
  "coexpression",
  "arabidopsis_coexpression_metrics.rds"
)

# Gene-level pleiotropy metrics generated by 03_calculate_hill_metrics.R
hill_file <- file.path(
  "results",
  "gene_pleiotropy_hill_metrics.csv"
)

# Gene-level tissue-specificity estimates
tau_file <- file.path(
  "data",
  "external",
  "tissue_specificity",
  "arabidopsis_tissue_specificity_tau.rds"
)

# Define outputs
output_dir <- "results"

dir.create(
  output_dir,
  recursive = TRUE,
  showWarnings = FALSE
)

# Merged gene-level dataset used for the correlation analyses
out_merged_file <- file.path(
  output_dir,
  "merged_hill_coexp.csv"
)

out_merged_tau_file <- file.path(
  output_dir,
  "merged_hill_tau.csv"
)

out_correlations_file <- file.path(
  output_dir,
  "spearman_correlation_results.csv"
)

# Load data 
coexp <- readRDS(
  coexp_file
)

hill <- read_csv(
  hill_file,
  show_col_types = FALSE
)

tau <- readRDS(
  tau_file
)

# Standardize gene identifiers
# Rename the TAIR10 gene identifier column so that all datasets use the same column name.
colnames(coexp)[colnames(coexp) == "TAIR_gene"] <- "gene"
colnames(tau)[colnames(tau) == "TAIR_gene"] <- "gene"

# Retain genes with a valid, positive Hill q = 1 value
hill <- hill %>%
  filter(
    !is.na(hill_q1),
    hill_q1 > 0
  )

# Co-expression network correlations
# Merge datasets
# Retain genes represented in both datasets.
merged <- hill %>%
  select(
    gene,
    trait_richness,
    total_effect_magnitude,
    H,
    hill_q1,
    magnitude,
    mean_of_means
  ) %>%
  inner_join(
    coexp %>%
      select(
        gene,
        node_degree,
        node_strength,
        node_closeness,
        node_betweenness
      ),
    by = "gene"
  ) %>%
  
  # Retain complete observations for all reported correlations.
  filter(
    !is.na(node_degree),
    !is.na(node_strength),
    !is.na(node_closeness),
    !is.na(node_betweenness)
  )

# Save merged dataset
write.csv(
  merged,
  out_merged_file,
  row.names = FALSE
)

# Calculate Spearman correlations
# Hill q = 1 versus co-expression network degree.
cor_hill_degree <- cor.test(
  merged$hill_q1,
  merged$node_degree,
  method = "spearman"
)

cor_hill_degree

# Hill q = 1 versus co-expression network strength.
cor_hill_strength <- cor.test(
  merged$hill_q1,
  merged$node_strength,
  method = "spearman"
)

cor_hill_strength

# Hill q = 1 versus co-expression network closeness.
cor_hill_closeness <- cor.test(
  merged$hill_q1,
  merged$node_closeness,
  method = "spearman"
)

cor_hill_closeness

# Hill q = 1 versus co-expression network betweenness.
cor_hill_betweenness <- cor.test(
  merged$hill_q1,
  merged$node_betweenness,
  method = "spearman"
)

cor_hill_betweenness

# Tissue specificity and GWAS-derived pleiotropy
# Merge gene-level Hill q = 1 estimates with tissue-specificity estimates
# This analysis is independent of co-expression network representation
merged_tau <- hill %>%
  select(
    gene,
    hill_q1
  ) %>%
  inner_join(
    tau %>%
      select(
        gene,
        tau_mean
      ),
    by = "gene"
  ) %>%
  filter(
    is.finite(hill_q1),
    is.finite(tau_mean)
  )

# Check the number of genes included
nrow(merged_tau)

# Save merged tissue-specificity dataset
write_csv(
  merged_tau,
  out_merged_tau_file
)

# Calculate Spearman correlation
cor_hill_tau <- cor.test(
  merged_tau$hill_q1,
  merged_tau$tau_mean,
  method = "spearman",
  exact = FALSE
)

cor_hill_tau

# Summarize correlation results
# Create a summary table containing sample sizes, Spearman correlation coefficients, and p-values
correlation_results <- tibble(
  comparison = c(
    "Hill q1 vs co-expression degree",
    "Hill q1 vs co-expression strength",
    "Hill q1 vs co-expression closeness",
    "Hill q1 vs co-expression betweenness",
    "Hill q1 vs tissue specificity (tau)"
  ),
  
  n_genes = c(
    nrow(merged),
    nrow(merged),
    nrow(merged),
    nrow(merged),
    nrow(merged_tau)
  ),
  
  spearman_rho = c(
    unname(cor_hill_degree$estimate),
    unname(cor_hill_strength$estimate),
    unname(cor_hill_closeness$estimate),
    unname(cor_hill_betweenness$estimate),
    unname(cor_hill_tau$estimate)
  ),
  
  p_value = c(
    cor_hill_degree$p.value,
    cor_hill_strength$p.value,
    cor_hill_closeness$p.value,
    cor_hill_betweenness$p.value,
    cor_hill_tau$p.value
  )
)

# Display results
print(correlation_results)

# Save correlation summary
write_csv(
  correlation_results,
  out_correlations_file
)
